/* Platform rules for @NAME@ on Nexvyn OS. Generated by scaffold.py; edit freely.
 * Source of truth: platform/capabilities.json in Nexvyn Port Studio. */
#ifndef NX_PORT_RULES_H
#define NX_PORT_RULES_H

#include <stdint.h>
#include "nexvyn/nxn_app.h"

/* Rule 1: poll nxn_should_quit at least every 250 ms, also inside long loads.
 * The OS marks the app "not responding" otherwise. Call nx_rules_pump() from loaders. */
#define NX_QUIT_POLL_MS 250
static inline int nx_rules_pump(void) { return nxn_should_quit(); }

/* Rule 2: vsync off. Pace frames yourself (fps cap from generated/nx_experience.h). */
#define NX_VSYNC 0

/* Rule 3: at most 3 real threads (more only add contention on the shared cores). */
#define NX_MAX_THREADS 3

/* Rule 4: never hold a lock across file or network I/O. Copy out under the lock, do I/O after it. */

/* Rule 5: read files in 256 KB to 1 MB blocks. Tiny reads and huge single reads are both slow. */
#define NX_READ_BLOCK_MIN (256u * 1024u)
#define NX_READ_BLOCK_MAX (1024u * 1024u)
static inline uint32_t nx_read_block(uint64_t remaining) {
    if (remaining >= NX_READ_BLOCK_MAX) return NX_READ_BLOCK_MAX;
    return remaining > NX_READ_BLOCK_MIN ? (uint32_t)remaining : NX_READ_BLOCK_MIN;
}

/* Rule 6: ship compressed textures (BC1/BC3/BC5; KTX ETC2/EAC for g3d). Do not upload RGBA8 for large assets. */

/* Preview APIs: private-preview, not in release SDKs. Use only behind the capability bit and keep a fallback. */
static inline uint32_t nx_memory_budget_mb(uint32_t fallback_mb) {
#if defined(NXN_CAP_MEMORY_BUDGET)
    uint32_t mb = 0;
    if (nxn_memory_budget_get(&mb) == 0 && mb) return mb;
#endif
    return fallback_mb; /* the app.json "memory" value */
}

static inline int nx_thread_hint(int wanted) {
    if (wanted > NX_MAX_THREADS) wanted = NX_MAX_THREADS;
#if defined(NXN_CAP_MEMORY_BUDGET)
    (void)nxn_thread_hint_request(wanted);
#endif
    return wanted;
}

#endif
